_shape(raw_member, raw_payment)
    if error:
        return {"ok": False, "error": error}
    status = raw_member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}
    handler = _HANDLERS.get(status)
    if handler is None:
        return {"ok": False, "error": "unknown status"}
    error = _validate_payment(raw_member, raw_payment)
    if error:
        return {"ok": False, "error": error}
    return handler(raw_member, raw_payment)
